import os
import sys

def solve():
    if os.path.exists("wormhole.in"):
        data = list(map(int, open("wormhole.in").read().split()))
    else:
        data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    x = [0] * (n + 1)
    y = [0] * (n + 1)
    for i in range(1, n + 1):
        x[i] = data[2 * i - 1]
        y[i] = data[2 * i]

    next_right = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if y[j] == y[i] and x[j] > x[i]:
                if next_right[i] == 0 or x[j] < x[next_right[i]]:
                    next_right[i] = j

    partner = [0] * (n + 1)

    def has_cycle():
        for start in range(1, n + 1):
            pos = start
            for _ in range(n):
                pos = next_right[partner[pos]]
                if pos == 0:
                    break
            if pos != 0:
                return True
        return False

    def dfs():
        first = 0
        for i in range(1, n + 1):
            if partner[i] == 0:
                first = i
                break
        if first == 0:
            return 1 if has_cycle() else 0
        total = 0
        for j in range(first + 1, n + 1):
            if partner[j] == 0:
                partner[first] = j
                partner[j] = first
                total += dfs()
                partner[first] = 0
                partner[j] = 0
        return total

    ans = dfs()
    if os.path.exists("wormhole.in"):
        with open("wormhole.out", "w") as f:
            f.write(f"{ans}\n")
    else:
        print(ans)

if __name__ == "__main__":
    solve()

