#include <cstdio>
#include <iostream>
using namespace std;

int N;
long long X[13], Y[13];
int partner[13], nextRight[13];

bool hasCycle() {
    for (int start = 1; start <= N; start++) {
        int pos = start;
        for (int step = 0; step < N; step++) {
            pos = nextRight[partner[pos]];
        }
        if (pos != 0) return true;
    }
    return false;
}

int countPairings() {
    int i = 1;
    while (i <= N && partner[i] != 0) i++;
    if (i > N) return hasCycle() ? 1 : 0;
    int total = 0;
    for (int j = i + 1; j <= N; j++) {
        if (partner[j] == 0) {
            partner[i] = j;
            partner[j] = i;
            total += countPairings();
            partner[i] = partner[j] = 0;
        }
    }
    return total;
}

int main() {
    if (FILE* f = fopen("wormhole.in", "r")) {
        fclose(f);
        freopen("wormhole.in", "r", stdin);
        freopen("wormhole.out", "w", stdout);
    }
    cin >> N;
    for (int i = 1; i <= N; i++) cin >> X[i] >> Y[i];
    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= N; j++) {
            if (Y[j] == Y[i] && X[j] > X[i]) {
                if (nextRight[i] == 0 || X[j] < X[nextRight[i]]) {
                    nextRight[i] = j;
                }
            }
        }
    }
    cout << countPairings() << '\n';
    return 0;
}

