        while (first <= N && partner[first] != 0) first++;
        if (first > N) return hasCycle() ? 1 : 0;
        int total = 0;
        for (int j = first + 1; j <= N; j++) {
            if (partner[j] == 0) {
                partner[first] = j;
                partner[j] = first;
                total += dfs();
                partner[first] = partner[j] = 0;
            }
        }
        return total;
    }

